BEGIN;
DROP SCHEMA IF EXISTS commerce CASCADE;
CREATE SCHEMA commerce;
SET timezone = 'UTC';
CREATE TABLE commerce.orders (order_id bigint NOT NULL, billing_customer_id integer NOT NULL, shipping_customer_id integer, status text NOT NULL, order_date date NOT NULL, placed_at timestamp(6) with time zone NOT NULL, local_placed_at timestamp(6) without time zone NOT NULL, pickup_time time(6) without time zone NOT NULL, total_minor bigint NOT NULL, tax_amount numeric(18,2) NOT NULL, currency text NOT NULL, PRIMARY KEY (order_id));
\copy commerce.orders FROM '/data/orders.csv' WITH (FORMAT csv, HEADER true, NULL '\N');
DO $$ BEGIN IF (SELECT count(*) FROM commerce.orders) <> 10 THEN RAISE EXCEPTION 'seed row count mismatch: orders'; END IF; END $$;
CREATE TABLE commerce.order_items (order_id bigint NOT NULL, line_no smallint NOT NULL, product_id integer NOT NULL, quantity integer NOT NULL, line_minor bigint NOT NULL, PRIMARY KEY (order_id,line_no));
\copy commerce.order_items FROM '/data/order_items.csv' WITH (FORMAT csv, HEADER true, NULL '\N');
DO $$ BEGIN IF (SELECT count(*) FROM commerce.order_items) <> 11 THEN RAISE EXCEPTION 'seed row count mismatch: order_items'; END IF; END $$;
CREATE TABLE commerce.refunds (refund_id bigint NOT NULL, order_id bigint NOT NULL, line_no smallint NOT NULL, refund_minor bigint NOT NULL, refund_date date NOT NULL, PRIMARY KEY (refund_id));
\copy commerce.refunds FROM '/data/refunds.csv' WITH (FORMAT csv, HEADER true, NULL '\N');
DO $$ BEGIN IF (SELECT count(*) FROM commerce.refunds) <> 5 THEN RAISE EXCEPTION 'seed row count mismatch: refunds'; END IF; END $$;
CREATE TABLE commerce.subscriptions (subscription_id bigint NOT NULL, customer_id integer NOT NULL, start_date date NOT NULL, end_date date, monthly_minor bigint NOT NULL, status text NOT NULL, PRIMARY KEY (subscription_id));
\copy commerce.subscriptions FROM '/data/subscriptions.csv' WITH (FORMAT csv, HEADER true, NULL '\N');
DO $$ BEGIN IF (SELECT count(*) FROM commerce.subscriptions) <> 5 THEN RAISE EXCEPTION 'seed row count mismatch: subscriptions'; END IF; END $$;
CREATE TABLE commerce.customer_region_history (customer_id integer NOT NULL, valid_from date NOT NULL, valid_to date, region text NOT NULL, PRIMARY KEY (customer_id,valid_from));
\copy commerce.customer_region_history FROM '/data/customer_region_history.csv' WITH (FORMAT csv, HEADER true, NULL '\N');
DO $$ BEGIN IF (SELECT count(*) FROM commerce.customer_region_history) <> 6 THEN RAISE EXCEPTION 'seed row count mismatch: customer_region_history'; END IF; END $$;
COMMIT;
